package dev.drakou111.sugarcane.gen;

/**
 * Per-biome sugar cane parameters for 1.16.1: how many times
 * {@code COUNT_HEIGHTMAP_DOUBLE} invokes the feature, and the feature's index
 * within {@code GenerationStep.Decoration.VEGETAL_DECORATION} (which is what
 * {@code setFeatureSeed} salts the RNG with).
 *
 * <p>Generated by walking the decompiled biome constructors and expanding every
 * {@code BiomeDefaultFeatures} helper in order. No structure registers at
 * VEGETAL_DECORATION, so the index needs no offset for structures.
 *
 * <p>Cross-checked against {@code RealWorldValidator}, which recovers the same
 * pairs empirically from generated chunks: desert 60/5, swamp 20/9, plains 10/6,
 * river 10/5, beach 10/4, snowy taiga 10/8, ocean 10/5 - 16 of 16 agree.
 *
 * <p>Biomes absent from this table do not generate sugar cane.
 */
public final class BiomeCaneConfig {

    private static final int[] COUNT = new int[256];
    private static final int[] INDEX = new int[256];

    private BiomeCaneConfig() {
    }

    private static void put(int biomeId, int count, int index) {
        COUNT[biomeId] = count;
        INDEX[biomeId] = index;
    }

    static {
        put(0, 10, 5);   // ocean
        put(1, 10, 6);   // plains
        put(2, 60, 5);   // desert
        put(3, 10, 5);   // mountains
        put(4, 10, 6);   // forest
        put(5, 10, 8);   // taiga
        put(6, 20, 9);   // swamp
        put(7, 10, 5);   // river
        put(10, 10, 5);   // frozen_ocean
        put(11, 10, 5);   // frozen_river
        put(12, 10, 5);   // snowy_tundra
        put(13, 10, 5);   // snowy_mountains
        put(14, 10, 5);   // mushroom_fields
        put(15, 10, 5);   // mushroom_field_shore
        put(16, 10, 4);   // beach
        put(17, 60, 5);   // desert_hills
        put(18, 10, 6);   // wooded_hills
        put(19, 10, 8);   // taiga_hills
        put(20, 10, 5);   // mountain_edge
        put(21, 10, 6);   // jungle
        put(22, 10, 6);   // jungle_hills
        put(23, 10, 5);   // jungle_edge
        put(24, 10, 5);   // deep_ocean
        put(25, 10, 4);   // stone_shore
        put(26, 10, 4);   // snowy_beach
        put(27, 10, 6);   // birch_forest
        put(28, 10, 6);   // birch_forest_hills
        put(29, 10, 6);   // dark_forest
        put(30, 10, 8);   // snowy_taiga
        put(31, 10, 8);   // snowy_taiga_hills
        put(32, 10, 9);   // giant_tree_taiga
        put(33, 10, 9);   // giant_tree_taiga_hills
        put(34, 10, 5);   // wooded_mountains
        put(35, 10, 6);   // savanna
        put(36, 10, 6);   // savanna_plateau
        put(37, 13, 4);   // badlands
        put(38, 13, 5);   // wooded_badlands_plateau
        put(39, 13, 4);   // badlands_plateau
        put(44, 10, 5);   // warm_ocean
        put(45, 10, 5);   // lukewarm_ocean
        put(46, 10, 5);   // cold_ocean
        put(47, 10, 5);   // deep_warm_ocean
        put(48, 10, 5);   // deep_lukewarm_ocean
        put(49, 10, 5);   // deep_cold_ocean
        put(50, 10, 5);   // deep_frozen_ocean
        put(129, 10, 5);   // sunflower_plains
        put(130, 60, 5);   // desert_lakes
        put(131, 10, 5);   // gravelly_mountains
        put(132, 10, 6);   // flower_forest
        put(133, 10, 8);   // taiga_mountains
        put(134, 20, 9);   // swamp_hills
        put(140, 10, 5);   // ice_spikes
        put(149, 10, 5);   // modified_jungle
        put(151, 10, 5);   // modified_jungle_edge
        put(155, 10, 6);   // tall_birch_forest
        put(156, 10, 6);   // tall_birch_hills
        put(157, 10, 6);   // dark_forest_hills
        put(158, 10, 8);   // snowy_taiga_mountains
        put(160, 10, 9);   // giant_spruce_taiga
        put(161, 10, 9);   // giant_spruce_taiga_hills
        put(162, 10, 5);   // modified_gravelly_mountains
        put(163, 10, 5);   // shattered_savanna
        put(164, 10, 5);   // shattered_savanna_plateau
        put(165, 13, 4);   // eroded_badlands
        put(166, 13, 5);   // modified_wooded_badlands_plateau
        put(167, 13, 4);   // modified_badlands_plateau
        put(168, 10, 6);   // bamboo_jungle
        put(169, 10, 6);   // bamboo_jungle_hills
    }

    /** Invocations per chunk, or 0 if this biome has no sugar cane feature. */
    public static int count(int biomeId) {
        return biomeId >= 0 && biomeId < 256 ? COUNT[biomeId] : 0;
    }

    /** Index within VEGETAL_DECORATION; only meaningful when count() > 0. */
    public static int index(int biomeId) {
        return biomeId >= 0 && biomeId < 256 ? INDEX[biomeId] : 0;
    }

    public static boolean hasSugarCane(int biomeId) {
        return count(biomeId) > 0;
    }
}
